@pytest.mark.parametrize('test_case', VERIFY_MESSAGE_SENT_SCENARIOS, ids=str)
def test_verify_message_sent(sqs_client, verifier, test_case):
    result = verifier.verify(test_case.event_obj.to_dict())

    assert result['statusCode'] == 200

    messages = sqs_client.receive_message(QueueUrl=SQS_QUEUE_URL)
    assert 'Messages' in messages
    assert len(messages['Messages']) == 1

    message_body = json.loads(messages['Messages'][0]['Body'])
    assert message_body == json.loads(test_case.event_obj.to_dict()['body'])


def test_verify_event_from_bot_ignored(sqs_client, verifier):
    event_container = EventContainer(
        event_obj=MockReactionAddedEvent(
            user=BOT_ID,
            reaction=CONFIG['sync_reaction'],
            channel='C1234567890',
            ts='1234567890.123456',
        ),
    )
    result = verifier.verify(event_container.to_dict())

    assert result['statusCode'] == 200
    body_json = json.loads(result['body'])
    assert body_json['message'] == 'Success'

    messages = sqs_client.receive_message(QueueUrl=SQS_QUEUE_URL)
    assert 'Messages' not in messages or len(messages['Messages']) == 0


def test_failed_verification_logs_do_not_include_signature_or_token(caplog, verifier):
    payload = {
        'token': 'deprecated-verification-token',
        'type': 'event_callback',
        'event': {
            'type': 'app_mention',
            'channel': 'C123',
            'thread_ts': '123.456',
            'text': 'hello',
        },
    }
    event_dict = {
        'headers': {'X-Slack-Signature': 'v0=not-a-real-signature'},
        'body': json.dumps(payload),
        'isBase64Encoded': False,
    }

    with caplog.at_level('ERROR'):
        result = verifier.verify(event_dict)

    assert result['statusCode'] == 403
    joined = '\n'.join(caplog.messages)
    assert 'Could not verify request' in joined
    assert 'C123_123.456' in joined
    assert 'hello' not in joined
    assert 'v0=not-a-real-signature' not in joined
    assert 'deprecated-verification-token' not in joined


